import java.io.File
import java.io.BufferedReader
import java.io.InputStreamReader

fun input(readFile: Boolean): String {
    return if (readFile) {
        File("sample.txt").readText()
    } else {
        val reader = BufferedReader(InputStreamReader(System.`in`))
        val sb = StringBuilder()
        var line: String?
        while (true) {
            line = reader.readLine() ?: break
            sb.append(line).append('\n')
        }
        sb.toString().trimEnd()
    }
}

fun solve(tokens: Iterator<String>) {
    val s1 = tokens.next().toCharArray().toList()
    val s2 = tokens.next().toCharArray().toList()

    var p1 = 0
    for (c in s1) {
        if (c == '+') {
            p1 += 1
        } else {
            p1 -= 1
        }
    }

    var p2 = 0
    var uc = 0
    for (c in s2) {
        when (c) {
            '+' -> p2 += 1
            '-' -> p2 -= 1
            else -> uc += 1
        }
    }

    val v = mutableListOf<Int>()
    for (bit in 0 until (1 shl uc)) {
        var p = p2
        for (i in 0 until uc) {
            if ((bit shr i) and 1 == 1) {
                p += 1
            } else {
                p -= 1
            }
        }
        v.add(p)
    }

    var cnt = 0
    for (x in v) {
        if (x == p1) {
            cnt += 1
        }
    }

    println(cnt.toDouble() / v.size.toDouble())
}

fun main() {
    val READ_FROM_FILE = false

    val s = input(READ_FROM_FILE)
    val tokens = s.split(Regex("\\s+")).filter { it.isNotEmpty() }.iterator()

    solve(tokens)
    // val t = tokens.next().toInt()
    // repeat(t) {}
}

